  const [backupBlob, setBackupBlob] = useState<string>(''); // selected backup content
  const [passphrase, setPassphrase] = useState<string>('');

  const pickFile = async () => {
    if (Platform.OS === 'web') {
      // Create a file input element programmatically and trigger it.
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = '*/*';
      // Keep it off-screen but attached to DOM so Playwright can detect the file chooser.
      input.style.position = 'fixed';
      input.style.top = '0';
      input.style.left = '0';
      input.style.opacity = '0';
      input.onchange = async (e: Event) => {
        const target = e.target as HTMLInputElement;
        const file = target.files?.[0];
        if (file) {
          try {
            const text = await file.text();
            setBackupBlob(text);
            setSnack('');
          } catch {
            setSnack('Failed to read file');
          }
        }
        // Clean up.
        document.body.removeChild(input);
      };
      document.body.appendChild(input);
      input.click();
      return;
    }
