{"code": "import os, subprocess, textwrap
os.makedirs('.scratch', exist_ok=True)
test = r'''
import React from 'react';
import renderer, { act } from 'react-test-renderer';
import Navigation from '../src/navigation';

jest.setTimeout(60000);

function findByLabel(root: any, label: string) {
  return root.findAll((n: any) => n.props && (n.props.accessibilityLabel === label || n.props['aria-label'] === label) && typeof (n.props.onPress || n.props.onClick) === 'function');
}

describe('nav', () => {
  it('settings -> export', async () => {
    let tree: any;
    await act(async () => { tree = renderer.create(<Navigation />); });
    await act(async () => { await new Promise(r => setTimeout(r, 200)); });
    const tabs = findByLabel(tree.root, 'Settings');
    console.log('settings tabs found', tabs.length);
    await act(async () => { tabs[0].props.onPress({}); });
    await act(async () => { await new Promise(r => setTimeout(r, 200)); });
    const exportBtns = findByLabel(tree.root, 'Export');
    console.log('export buttons', exportBtns.length);
    try {
      await act(async () => { exportBtns[0].props.onPress({}); });
      await act(async () => { await new Promise(r => setTimeout(r, 300)); });
      console.log('clicked export OK');
    } catch (e: any) {
      console.log('ERROR clicking export:', e && e.message);
      console.log((e && e.stack || '').split('\n').slice(0, 20).join('\n'));
    }
  });
});
'''
open('.scratch/nav.test.tsx','w').write(test)
p = subprocess.run(['npx','jest','--ci','.scratch/nav.test.tsx'], capture_output=True, text=True)
print(p.stdout[-6000:])
print('STDERR', p.stderr[-10000:])
"}

