{"path": "src/screens/RestoreScreenShared.tsx", "content": "import React, { useState } from 'react';
import { View } from 'react-native';
import { ActivityIndicator, Snackbar } from 'react-native-paper';
import { Screen, PrimaryButton, FormField } from '../components/ui';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import * as DocumentPicker from 'expo-document-picker';
import * as FileSystem from 'expo-file-system';
import { restoreBackup } from '../lib/backup';
import { getStore } from '../lib/storage';

/** Restore screen – selects a backup file and restores it. */
export default function RestoreScreenShared() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [loading, setLoading] = useState(false);
  const [snack, setSnack] = useState<string>('');
  const [backupBlob, setBackupBlob] = useState<string>('');
  const [passphrase, setPassphrase] = useState<string>('');

  const pickFile = async () => {
    try {
      const result: any = await DocumentPicker.getDocumentAsync({ type: '*/*' });
      if (!result.canceled && result.assets && result.assets[0]?.uri) {
        const uri = result.assets[0].uri;
        const content = uri.startsWith('file://') || uri.startsWith('content://')
          ? await FileSystem.readAsStringAsync(uri)
          : await (await fetch(uri)).text();
        setBackupBlob(content);
        setSnack('');
      }
    } catch {
      setSnack('Failed to pick file');
    }
  };

  const onRestore = async () => {
    if (!backupBlob || !passphrase) {
      setSnack('Enter passphrase.');
      return;
    }
    try {
      setLoading(true);
      const store = getStore();
      await restoreBackup(store, backupBlob, passphrase);
      setSnack('Data restored successfully.');
    } catch {
      setSnack('Invalid passphrase or corrupted backup file.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Screen title="Restore backup">
      <View style={{ gap: 12 }}>
        <PrimaryButton label="Back" variant="secondary" onPress={() => navigation.goBack()} />
        <PrimaryButton label="Select backup file" variant="secondary" onPress={pickFile} disabled={loading} />
        <FormField label="Backup passphrase" value={passphrase} onChangeText={setPassphrase} secureTextEntry />
        {loading && <ActivityIndicator accessibilityLabel="Restoring data" />}
        <PrimaryButton label="Restore" variant="primary" onPress={onRestore} disabled={loading} />
        <Snackbar visible={!!snack} onDismiss={() => setSnack('')} duration={2000}>
          {snack}
        </Snackbar>
      </View>
    </Screen>
  );
}
"}

{"path":"src/screens/ExportScreen.tsx","content":"import React, { useState } from 'react';
import { View } from 'react-native';
import { ActivityIndicator, Snackbar, Text } from 'react-native-paper';
import { Screen, PrimaryButton } from '../components/ui';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { generateCsv } from '../lib/exportCsv';
import { generatePdf } from '../lib/exportPdf';
import * as Sharing from 'expo-sharing';
import * as FileSystem from 'expo-file-system';

/** ExportScreen that actually generates CSV/PDF files and shares them. */
export default function ExportScreen() {
  const [loading, setLoading] = useState(false);
  const [snack, setSnack] = useState<string>('');
  const navigation = useNavigation<NavigationProp<any>>();

  const shareFile = async (uri: string, mimeType: string, filename: string) => {
    try {
      await Sharing.shareAsync(uri, { mimeType, dialogTitle: filename });
    } catch (e) {
      // Sharing may fail on web; ignore for UI flow.
    }
  };

  const exportCsv = async () => {
    setLoading(true);
    try {
      const csv = await generateCsv();
      const dir = ((FileSystem as any).cacheDirectory || (FileSystem as any).documentDirectory) as string;
      const fileUri = dir + 'export.csv';
      await (FileSystem as any).writeAsStringAsync(fileUri, csv, { encoding: (FileSystem as any).EncodingType.UTF8 });
      await shareFile(fileUri, 'text/csv', 'export.csv');
      setSnack('Export ready to share');
    } catch (e) {
      setSnack('Export failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  const exportPdf = async () => {
    setLoading(true);
    try {
      const pdfUri = await generatePdf();
      await shareFile(pdfUri, 'application/pdf', 'export.pdf');
      setSnack('Export ready to share');
    } catch (e) {
      setSnack('Export failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Screen title="Export data">
      <View style={{ gap: 12 }}>
        <PrimaryButton label="Back" variant="secondary" onPress={() => navigation.goBack()} />
        <PrimaryButton label="Export CSV" variant="primary" onPress={exportCsv} disabled={loading} />
        <PrimaryButton label="Export PDF" variant="primary" onPress={exportPdf} disabled={loading} />
        {loading && <ActivityIndicator accessibilityLabel="Generating export" />}
        {snack ? <Text>{snack}</Text> : null}
      </View>
      <Snackbar visible={!!snack} onDismiss={() => setSnack('')} duration={3000}>
        {snack}
      </Snackbar>
    </Screen>
  );
}
"}

