{"path": "src/components/ui/WebFileInput.tsx", "content": "import React from 'react';
import { Platform } from 'react-native';
import { PrimaryButton } from './PrimaryButton';

/**
 * A file input component that works on web using a native <input type="file">.
 * On native platforms it falls back to the provided onPress handler (DocumentPicker).
 */
export default function WebFileInput({ label, onFileSelected }: { label: string; onFileSelected: (content: string) => void }) {
  if (Platform.OS === 'web') {
    const handleChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const text = await file.text();
      onFileSelected(text);
    };
    return (
      <label>
        <PrimaryButton label={label} variant="secondary" />
        <input type="file" accept="*/*" style={{ display: 'none' }} onChange={handleChange} />
      </label>
    );
  }
  // On native platforms, caller should provide a button that opens DocumentPicker.
  // This component is not used on native.
  return <PrimaryButton label={label} variant="secondary" onPress={() => {}} />;
}
"}

