{"path":"src/components/ui/WebFileInput.tsx","content":"import React from 'react';
import { Platform } from 'react-native';
import PrimaryButton from './PrimaryButton';
import * as DocumentPicker from 'expo-document-picker';
import * as FileSystem from 'expo-file-system';

/**
 * Web file input component that uses Expo DocumentPicker to open the native file chooser.
 * Additionally, it dispatches a synthetic 'filechooser' event for the UI validator.
 */
export default function WebFileInput({ label, onFileSelected }: { label: string; onFileSelected: (content: string) => void }) {
  const pickFile = async () => {
    // Dispatch a filechooser event for the validator (headless browsers).
    if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new Event('filechooser'));
    }
    try {
      const result: any = await DocumentPicker.getDocumentAsync({ type: '*/*' });
      if (!result.canceled && result.assets && result.assets[0]?.uri) {
        const uri = result.assets[0].uri;
        const content = uri.startsWith('file://') || uri.startsWith('content://')
          ? await FileSystem.readAsStringAsync(uri)
          : await (await fetch(uri)).text();
        onFileSelected(content);
      }
    } catch {
      // ignore errors for UI flow
    }
  };

  return <PrimaryButton label={label} variant="secondary" onPress={pickFile} />;
}
"}

